
/*
 * PDF Graph Integration
 *
 * Loads PNG graphs generated by sampleGraph.js
 * and adds them to the downloaded jsPDF report.
 *
 * NOTE: Graphs currently contain SAMPLE data.
 */

const PDFGraphIntegration = {

    async loadImage(url) {
        const response = await fetch(url);

        if (!response.ok) {
            throw new Error(
                `Unable to load graph: ${url} (HTTP ${response.status})`
            );
        }

        const blob = await response.blob();

        return new Promise((resolve, reject) => {
            const reader = new FileReader();

            reader.onload = () => resolve(reader.result);
            reader.onerror = () => reject(
                new Error(`Unable to read graph: ${url}`)
            );

            reader.readAsDataURL(blob);
        });
    },


    getGraphList(evaluations) {
        const basePath = "../../../../report-graphs/output/";


        const graphs = [
            {
                title: "Insight - Initial",
                file: "insight-initial.png"
            },
            {
                title: "Insight - Delayed",
                file: "insight-delayed.png"
            },
            {
                title: "Self-Awareness Comparison",
                file: "self-awareness.png"
            },
            {
                title: "Influence Comparison",
                file: "influence-comparison.png"
            }
        ];

        return graphs.map(graph => ({
            ...graph,
            url: basePath + graph.file
        }));
    },


    async addGraphsToPDF(pdf, evaluations) {
        const graphs = this.getGraphList(evaluations);

        if (graphs.length === 0) {
            throw new Error(
                "No graphs available for the selected evaluations."
            );
        }

        for (const graph of graphs) {
            const imageData = await this.loadImage(graph.url);

            // Get the actual image dimensions.
            const dimensions = pdf.getImageProperties(imageData);

            const pageWidth = pdf.internal.pageSize.getWidth();
            const pageHeight = pdf.internal.pageSize.getHeight();

            const margin = 15;
            const top = 35;
            const bottom = 25;

            const availableWidth = pageWidth - margin * 2;
            const availableHeight =
                pageHeight - top - bottom;

            const scale = Math.min(
                availableWidth / dimensions.width,
                availableHeight / dimensions.height
            );

            const imageWidth = dimensions.width * scale;
            const imageHeight = dimensions.height * scale;

            const imageX = (pageWidth - imageWidth) / 2;

            // Add a new page for each graph.
            pdf.addPage();

            pdf.setFontSize(16);
            pdf.text(graph.title, margin, 20);

            pdf.addImage(
                imageData,
                "PNG",
                imageX,
                top,
                imageWidth,
                imageHeight
            );

            // Explicitly label sample results.
            pdf.setFontSize(9);
            pdf.setTextColor(180, 50, 50);

            pdf.text(
                "DEMONSTRATION DATA - Not actual participant results",
                margin,
                pageHeight - 12
            );

            pdf.setTextColor(0, 0, 0);
        }
    }
};
